con:config.con:script:
// Assertions: HTTP response, valid JSON object, expected referral membership and routing.
import groovy.json.JsonSlurper

// === AUHN EVIDENCE CAPTURE - automated request / response / expected / observed ===
try {
    def _auhnCaseId = 'REF132_043_POS'
    def _auhnTestCase = testRunner.testCase
    def _auhnProject = _auhnTestCase.testSuite.project
    def _auhnStep = _auhnTestCase.getTestStepByName('02 Execute REST Request')
    def _auhnRestRequest = _auhnStep.getTestRequest()
    def _auhnRestResponse = _auhnRestRequest.getResponse()
    def _auhnRequestText = _auhnRestRequest.getRequestContent() ?: (_auhnStep.getPropertyValue('Request') ?: '')
    def _auhnResponseText = _auhnStep.getPropertyValue('Response') ?: (_auhnRestResponse?.getContentAsString() ?: '')
    def _auhnFolderPath = _auhnProject.getPropertyValue('AUHN_EVIDENCE_DIR')?.trim()
    if (!_auhnFolderPath) {
        _auhnFolderPath = new File(System.getProperty('user.home'), 'Downloads/AUHN_Evidence').getAbsolutePath()
    }
    def _auhnFolder = new File(_auhnFolderPath)
    if (!_auhnFolder.exists() && !_auhnFolder.mkdirs()) throw new IOException('Could not create evidence folder '+_auhnFolderPath)
    new File(_auhnFolder, _auhnCaseId+'.request.json').setText(_auhnRequestText, 'UTF-8')
    new File(_auhnFolder, _auhnCaseId+'.response.json').setText(_auhnResponseText, 'UTF-8')
    def _auhnMeta = new java.util.Properties()
    _auhnMeta.setProperty('caseId', _auhnCaseId)
    _auhnMeta.setProperty('suite', _auhnTestCase.testSuite.name)
    _auhnMeta.setProperty('testName', _auhnTestCase.name)
    _auhnMeta.setProperty('expectedHttpCodes', '200,201,202')
    _auhnMeta.setProperty('expectedRequiredCodes', '043')
    _auhnMeta.setProperty('expectedForbiddenCodes', '')
    _auhnMeta.setProperty('expectedRouting', 'UND')
    _auhnMeta.setProperty('expectedDriverNumber', '1')
    _auhnMeta.setProperty('expectedDriverReferral', '043')
    _auhnMeta.setProperty('expectedExactReferralCode', '')
    _auhnMeta.setProperty('expectedExactReferralCount', '')
    _auhnMeta.setProperty('captureTime', new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss Z").format(new Date()))
    _auhnMeta.setProperty('actualHttpStatus', (_auhnRestResponse?.getStatusCode() ?: '').toString())
    _auhnMeta.setProperty('actualRouting', '')
    _auhnMeta.setProperty('actualReferralCodes', '')
    _auhnMeta.setProperty('actualDriverNumbers', '')
    try {
        def _auhnData = _auhnResponseText?.trim() ? new groovy.json.JsonSlurper().parseText(_auhnResponseText) : [:]
        def _auhnArea = _auhnData instanceof Map && _auhnData.auDecisionArea instanceof Map ? _auhnData.auDecisionArea : [:]
        _auhnMeta.setProperty('actualRouting', (_auhnArea.wuc121_routing_destination ?: '').toString().trim())
        def _auhnReasons = _auhnArea.wuc121_routing_reasons instanceof List ? _auhnArea.wuc121_routing_reasons : []
        def _auhnReal = _auhnReasons.findAll { it instanceof Map && it.wuc121_rsn_code != null && it.wuc121_rsn_code.toString().trim() && it.wuc121_rsn_code.toString().trim().padLeft(3,'0') != '000' }
        _auhnMeta.setProperty('actualReferralCodes', _auhnReal.collect { it.wuc121_rsn_code.toString().trim().padLeft(3,'0') }.join(','))
        _auhnMeta.setProperty('actualDriverNumbers', _auhnReal.collect { (it.wuc121_rsn_code?.toString()?.trim()?.padLeft(3,'0') ?: '') + ':' + (it.wuc121_rsn_driver_number ?: '').toString().trim() }.join(','))
    } catch (Exception _auhnJsonEx) {
        _auhnMeta.setProperty('responseParseError', _auhnJsonEx.message ?: _auhnJsonEx.class.name)
    }
    new File(_auhnFolder, _auhnCaseId+'.properties').withOutputStream { _auhnOut -> _auhnMeta.store(_auhnOut, 'AUHN internal test evidence - no HTTP authorization headers stored') }
} catch (Throwable _auhnCaptureEx) {
    log.warn('AUHN test evidence capture failed: '+_auhnCaptureEx.message)
}
// === END AUHN EVIDENCE CAPTURE ===


def step = testRunner.testCase.getTestStepByName('02 Execute REST Request')
def response = step.getTestRequest().getResponse()
assert response != null : 'No HTTP response - verify host, SSL, authentication and REST path'
def status = response.getStatusCode()
assert status >= 200 && status < 300 : 'Expected HTTP 2xx but received ' + status + ' | ' + (step.getPropertyValue('Response') ?: '').take(500)
def raw = step.getPropertyValue('Response')
assert raw?.trim() : 'Empty response body'
def root
try { root = new JsonSlurper().parseText(raw) }
catch (Exception ex) { throw new AssertionError('Response is not valid JSON: '+ ex.message) }
assert root instanceof Map : 'Expected a JSON response object'
def area = root.auDecisionArea
assert area instanceof Map : 'Missing auDecisionArea response object'
assert area.containsKey('wuc121_routing_destination') : 'Missing wuc121_routing_destination'
assert area.wuc121_routing_reasons instanceof List : 'Missing wuc121_routing_reasons array'
def reasons = area.wuc121_routing_reasons.findAll { it instanceof Map }.collect { it.wuc121_rsn_code == null ? '' : it.wuc121_rsn_code.toString().trim().padLeft(3,'0') }
// Do not compare padded zero/empty OCCURS records.
reasons = reasons.findAll { it && it != '000' }
def required = ['043']
def forbidden = []
required.each { code -> assert reasons.contains(code) : 'Missing expected referral '+code+'; actual='+reasons }
forbidden.each { code -> assert !reasons.contains(code) : 'Unexpected referral '+code+'; actual='+reasons }
def destination = area.wuc121_routing_destination == null ? '' : area.wuc121_routing_destination.toString().trim()
assert destination == 'UND' : 'Expected routing destination UND, got '+destination
def rec = area.wuc121_routing_reasons.find { it instanceof Map && ((it.wuc121_rsn_code ?: '').toString().trim().padLeft(3,'0') == '043') }; assert rec != null && rec.wuc121_rsn_driver_number != null && rec.wuc121_rsn_driver_number.toString().trim().toInteger() == 1 : 'Expected driver ID 1 in referral 043'
// No exact referral count requirement for this scenario
log.info('PASS '+testRunner.testCase.name+' | HTTP '+status+' | route='+destination+' | referrals='+reasons)

