// AUHN Wave 1+2 unit test: business assertions and per-case JSON evidence.
import groovy.json.JsonSlurper
import java.util.Properties

def caseId = 'W2_REF002_328_POS'
def targetRule = 'REF-002_DriverNBRules'
def expectedRequired = ['328']
def expectedForbidden = []
def expectedRoute = 'UND'
def expectedDriverCode = '328'
def expectedDriverId = 1
def candidate = true   // Not certified by live AAA execution

def project = testRunner.testCase.testSuite.project
def step = testRunner.testCase.getTestStepByName('02 Execute REST Request')
def request = step.getTestRequest()
def response = request.getResponse()
def requestText = request.getRequestContent() ?: (step.getPropertyValue('Request') ?: '')
def raw = step.getPropertyValue('Response') ?: (response?.getContentAsString() ?: '')
def status = response?.getStatusCode() ?: 0

def dest = ''
def codeList = []
def records = []
def parseProblem = ''
try {
    def parsed = raw?.trim() ? new JsonSlurper().parseText(raw) : [:]
    def area = parsed instanceof Map ? parsed.auDecisionArea : null
    if (area instanceof Map) {
        dest = (area.wuc121_routing_destination ?: '').toString().trim()
        records = area.wuc121_routing_reasons instanceof List ? area.wuc121_routing_reasons.findAll { it instanceof Map } : []
        codeList = records.collect { (it.wuc121_rsn_code ?: '').toString().trim() }.findAll { it && it != '000' && !it.toUpperCase().startsWith('X') }.collect { it.padLeft(3,'0') }
    }
} catch (Exception ex) { parseProblem = ex.message ?: ex.toString() }

// Capture actual request and response before evaluating assertions (including failures).
try {
    def evidenceDir = project.getPropertyValue('AUHN_EVIDENCE_DIR')?.trim()
    if (!evidenceDir) evidenceDir = new File(System.getProperty('user.home'), 'Downloads/AUHN_Evidence').absolutePath
    def folder = new File(evidenceDir)
    if (!folder.exists() && !folder.mkdirs()) throw new IOException('Unable to create '+evidenceDir)
    new File(folder, caseId+'.request.json').setText(requestText, 'UTF-8')
    new File(folder, caseId+'.response.json').setText(raw, 'UTF-8')
    def meta = new Properties()
    meta.setProperty('caseId',caseId)
    meta.setProperty('suite',testRunner.testCase.testSuite.name)
    meta.setProperty('testName',testRunner.testCase.name)
    meta.setProperty('targetRule',targetRule)
    meta.setProperty('validationStatus','CANDIDATE - live outcome not independently confirmed')
    meta.setProperty('expectedHttpCodes','200,201,202')
    meta.setProperty('expectedRequiredCodes',expectedRequired.join(','))
    meta.setProperty('expectedForbiddenCodes',expectedForbidden.join(','))
    meta.setProperty('expectedRouting',expectedRoute ?: '')
    meta.setProperty('expectedDriverNumber',expectedDriverId == null ? '' : expectedDriverId.toString())
    meta.setProperty('expectedDriverReferral',expectedDriverCode ?: '')
    meta.setProperty('actualHttpStatus',status.toString())
    meta.setProperty('actualRouting',dest)
    meta.setProperty('actualReferralCodes',codeList.join(','))
    meta.setProperty('actualDriverNumbers', records.collect { (it.wuc121_rsn_code ?: '').toString().trim()+':'+(it.wuc121_rsn_driver_number ?: '').toString().trim() }.join(','))
    meta.setProperty('responseParseError',parseProblem ?: '')
    meta.setProperty('captureTime',new java.text.SimpleDateFormat('yyyy-MM-dd HH:mm:ss Z').format(new Date()))
    new File(folder,caseId+'.properties').withOutputStream { out -> meta.store(out,'AUHN internal test evidence; credentials and headers excluded') }
} catch (Exception ex) { log.warn('AUHN evidence capture failed: '+ ex.message) }

assert response != null : 'No HTTP response: verify SSL, endpoint and authentication'
assert status in [200,201,202] : 'Expected HTTP 200/201/202, got '+status+'; response='+raw.take(500)
assert raw?.trim() : 'HTTP response body is empty'
assert !parseProblem : 'Invalid response JSON: '+parseProblem
def parsed = new JsonSlurper().parseText(raw)
assert parsed instanceof Map && parsed.auDecisionArea instanceof Map : 'Missing auDecisionArea object'
assert parsed.auDecisionArea.containsKey('wuc121_routing_destination') : 'Missing routing destination field'
assert parsed.auDecisionArea.wuc121_routing_reasons instanceof List : 'Missing routing reasons array'
expectedRequired.each { code -> assert codeList.contains(code) : 'Expected referral '+code+' for '+targetRule+' but found '+codeList }
expectedForbidden.each { code -> assert !codeList.contains(code) : 'Unexpected referral '+code+' for '+targetRule+'; actual '+codeList }
if (expectedRoute) assert dest == expectedRoute : 'Expected routing destination '+expectedRoute+', got '+dest
if (expectedDriverCode && expectedDriverId != null) {
    def record = records.find { (it.wuc121_rsn_code ?: '').toString().trim().padLeft(3,'0') == expectedDriverCode && (it.wuc121_rsn_driver_number ?: '').toString().trim().isInteger() && it.wuc121_rsn_driver_number.toString().trim().toInteger() == expectedDriverId }
    assert record != null : 'Expected driver '+expectedDriverId+' for referral '+expectedDriverCode
}
log.info('AUHN PASS: '+testRunner.testCase.name+'; status='+status+'; destination='+dest+'; referrals='+codeList)

